import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { newId } from "@/lib/id";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "@/tests/server/_support/fixtures";
import type { LabelId, OrgId } from "@/types/common";

function assert(cond: unknown, message: string): asserts cond {
  if (!cond) throw new Error(message);
}

const cleanup = await useTemporaryDatabase();
try {
  const parsed = mergeLabelsSchema.safeParse({
    orgId: newId(),
    sourceLabelId: newId(),
    targetLabelId: newId(),
  });
  assert(parsed.success, "distinct ids should parse");

  const same = newId();
  const rejected = mergeLabelsSchema.safeParse({
    orgId: newId(),
    sourceLabelId: same,
    targetLabelId: same,
  });
  assert(!rejected.success, "same ids should fail schema");

  const bad = mergeLabelsSchema.safeParse({
    orgId: "nope",
    sourceLabelId: newId(),
    targetLabelId: newId(),
  });
  assert(!bad.success, "bad org id should fail");

  const tenant = await createTenant("mergea", "growth");
  const other = await createTenant("mergeb", "growth");
  const actor = tenant.actors.owner;
  const orgId = tenant.org.id;

  const source = await labelService.createLabel(actor, {
    orgId,
    name: "defect",
    color: "#ff0000",
    description: "source",
  });
  const target = await labelService.createLabel(actor, {
    orgId,
    name: "bug",
    color: "#00ff00",
    description: "target",
  });
  const untouched = await labelService.createLabel(actor, {
    orgId,
    name: "chore",
    color: "#0000ff",
    description: null,
  });
  const foreign = await labelService.createLabel(other.actors.owner, {
    orgId: other.org.id,
    name: "defect",
    color: "#111111",
    description: "other",
  });

  const onlySource = await issueService.createIssue(
    actor,
    { ...issueInput(orgId, tenant.project.id, { title: "only source" }), labelIds: [source.id] },
  );
  const both = await issueService.createIssue(
    actor,
    {
      ...issueInput(orgId, tenant.project.id, { title: "both" }),
      labelIds: [source.id, target.id],
    },
  );
  const onlyTarget = await issueService.createIssue(
    actor,
    { ...issueInput(orgId, tenant.project.id, { title: "only target" }), labelIds: [target.id] },
  );
  const neither = await issueService.createIssue(
    actor,
    { ...issueInput(orgId, tenant.project.id, { title: "neither" }), labelIds: [untouched.id] },
  );
  const archived = await issueService.createIssue(
    actor,
    { ...issueInput(orgId, tenant.project.id, { title: "archived" }), labelIds: [source.id] },
  );
  await issueService.archiveIssue(actor, orgId, archived.id);

  const foreignIssue = await issueService.createIssue(
    other.actors.owner,
    {
      ...issueInput(other.org.id, other.project.id, { title: "foreign" }),
      labelIds: [foreign.id],
    },
  );

  await assertRejects(
    labelService.mergeLabels(tenant.actors.viewer, {
      orgId,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    }),
    PermissionDeniedError,
    "viewer",
  );
  assert(await labelRepo.findLabelById(orgId, source.id), "source remains after denied");

  await assertRejects(
    labelService.mergeLabels(actor, {
      orgId: other.org.id,
      sourceLabelId: source.id,
      targetLabelId: target.id,
    }),
    TenantScopeError,
    "cross tenant",
  );

  await assertRejects(
    labelService.mergeLabels(actor, {
      orgId,
      sourceLabelId: foreign.id,
      targetLabelId: target.id,
    }),
    NotFoundError,
    "foreign source",
  );
  assert(await labelRepo.findLabelById(other.org.id, foreign.id), "foreign label remains");

  await assertRejects(
    labelService.mergeLabels(actor, {
      orgId,
      sourceLabelId: source.id,
      targetLabelId: foreign.id,
    }),
    NotFoundError,
    "foreign target",
  );

  const missing = newId() as LabelId;
  await assertRejects(
    labelService.mergeLabels(actor, {
      orgId,
      sourceLabelId: missing,
      targetLabelId: target.id,
    }),
    NotFoundError,
    "missing source",
  );

  await assertRejects(
    labelService.mergeLabels(actor, {
      orgId,
      sourceLabelId: source.id,
      targetLabelId: source.id,
    }),
    Error,
    "self merge",
  );
  assert(await labelRepo.findLabelById(orgId, source.id), "self merge keeps source");
  const still = await issueRepo.findIssueById(orgId, onlySource.id);
  assert(still?.labelIds.includes(source.id), "self merge keeps assignment");

  const result = await labelService.mergeLabels(actor, {
    orgId,
    sourceLabelId: source.id,
    targetLabelId: target.id,
  });
  assert(result.issuesRelabelled === 3, `count ${result.issuesRelabelled}`);
  assert(result.label.id === target.id, "returns target");
  assert(result.label.name === "bug" && result.label.color === "#00ff00", "target fields");
  assert(result.label.description === "target", "target description");
  assert(!(await labelRepo.findLabelById(orgId, source.id)), "source deleted");
  const targetAfter = await labelRepo.findLabelById(orgId, target.id);
  assert(targetAfter?.name === "bug" && targetAfter.color === "#00ff00", "target row unchanged");
  assert(targetAfter?.description === "target", "target description unchanged");

  const ids = async (issueId: typeof onlySource.id) =>
    (await issueRepo.findIssueById(orgId, issueId))?.labelIds ?? [];

  const a = await ids(onlySource.id);
  const b = await ids(both.id);
  const c = await ids(onlyTarget.id);
  const d = await ids(neither.id);
  const e = await ids(archived.id);
  assert(a.length === 1 && a[0] === target.id, `only source -> ${a.join(",")}`);
  assert(b.length === 1 && b[0] === target.id, `both -> ${b.join(",")}`);
  assert(c.length === 1 && c[0] === target.id, `only target -> ${c.join(",")}`);
  assert(d.length === 1 && d[0] === untouched.id, `neither -> ${d.join(",")}`);
  assert(e.length === 1 && e[0] === target.id, `archived -> ${e.join(",")}`);

  const foreignAfter = await issueRepo.findIssueById(other.org.id, foreignIssue.id);
  assert(foreignAfter?.labelIds.includes(foreign.id), "other org issue unchanged");
  assert(!(foreignAfter?.labelIds.includes(target.id)), "other org did not gain target");

  console.log("ok", result.issuesRelabelled);
} finally {
  cleanup();
}

async function assertRejects(p: Promise<unknown>, type: new (...args: never[]) => Error, label: string) {
  try {
    await p;
  } catch (error) {
    if (error instanceof type) return;
    throw new Error(`${label} threw ${error instanceof Error ? error.name : error}`);
  }
  throw new Error(`${label} did not throw`);
}
